mapper.sql:
FROM tc_product p JOIN tc_sku s ON s.tenant_id=p.tenant_id AND s.product_id=p.id
WHERE p.tenant_id=#{tenant}
  AND s.id=(SELECT MIN(primary_sku.id) FROM tc_sku primary_sku WHERE primary_sku.tenant_id=p.tenant_id AND primary_sku.product_id=p.id)
AND p.product_no=#{q.filters.productNo}
AND p.name=#{q.filters.name}
AND p.status=#{q.filters.status}

  AND EXISTS (SELECT 1 FROM tc_sku match_sku WHERE match_sku.tenant_id=p.tenant_id AND match_sku.product_id=p.id AND match_sku.sku_no=#{q.filters.skuNo})

mapper.select:
SELECT p.id AS productId,s.id AS skuId,p.name AS name,p.status AS status,p.version AS version,
  s.unit_price AS unitPrice,s.currency AS currency,p.published_revision AS publishedRevision,p.product_no AS productNo,p.image_url AS imageUrl

AND p.id > #{q.after}
ORDER BY p.id LIMIT #{q.limit}

SELECT p.id AS productId,s.id AS skuId,p.name AS name,p.status AS status,p.version AS version,
  s.unit_price AS unitPrice,s.currency AS currency,p.published_revision AS publishedRevision,p.product_no AS productNo,p.image_url AS imageUrl

ORDER BY p.id LIMIT #{q.limit} OFFSET #{offset}
